// 呼び出しの深さを字下げで表して、フレームが積まれて消える様子を見る
static String indent(int depth) {
    return "  ".repeat(depth);
}

static int tax(int price, int depth) {
    System.out.println(indent(depth) + "→ tax(" + price + ") のフレームを積む");
    int result = price * 10 / 100;    // result は tax のフレームにあるローカル変数
    System.out.println(indent(depth) + "← tax が " + result + " を返して、フレームが消える");
    return result;
}

static int total(int price, int qty, int depth) {
    System.out.println(indent(depth) + "→ total(" + price + ", " + qty + ") のフレームを積む");
    int subtotal = price * qty;       // subtotal は total のフレームにある
    int sum = subtotal + tax(subtotal, depth + 1);
    System.out.println(indent(depth) + "← total が " + sum + " を返して、フレームが消える");
    return sum;
}

// ここを変えてみよう:total の中で tax を2回呼ぶと、積まれ方はどう変わる?
System.out.println("main のフレームから呼び出す");
int answer = total(500, 3, 1);
System.out.println("main に戻った: " + answer);
