class Cart {
    String owner;
    int points;

    Cart(String owner, int points) {
        this.owner = owner;
        this.points = points;
    }
}

static void addPoints(Cart c, int p) {
    c.points += p;              // 矢印の先(同じ実体)を書き換える → 呼び出し元から見える
}

static void replace(Cart c) {
    c = new Cart("別人", 0);    // 引数 c の矢印を付け替えただけ → 呼び出し元は変わらない
    c.points = 9999;
}

static void addOne(int n) {
    n++;                        // n は値のコピー。呼び出し元の int は変わらない
}

