import java.util.ArrayList;
import java.util.List;

class Report {
    final String name;
    final int[] data = new int[1000];   // int 1000 個 = 4000 バイト(約4KB)

    Report(String name) {
        this.name = name;
    }
}

class ReportCache {
    // static はクラスが使われている間ずっと生きている = ここから辿れる実体も生き続ける
    static final List<Report> ALL = new ArrayList<>();
}

static void handleRequest(int no) {
    Report r = new Report("report-" + no);
    ReportCache.ALL.add(r);   // 「あとで使うかも」と取っておく
    // r(ローカル変数)はメソッドを出ると消えるが、ALL から辿れるので実体は GC されない
}

// ここを変えてみよう:1000 を 10 倍にすると、溜まる量も 10 倍になる
for (int i = 1; i <= 1000; i++) {
    handleRequest(i);
}
int kept = ReportCache.ALL.size();
System.out.println("リクエストは終わったのに残っている Report: " + kept + " 個");
System.out.println("配列だけで約 " + (kept * 4000 / 1000) + "KB(計算上の値)");

ReportCache.ALL.clear();      // 参照を外せば、次の GC で回収できる状態になる
System.out.println("clear 後: " + ReportCache.ALL.size() + " 個");

class Deep {
    static int depth = 0;

    static void dive() {
        depth++;
        dive();               // 終了条件がないので、フレームを積み続ける
    }

    static long sumLoop(int n) {
        long sum = 0;
        for (int i = 1; i <= n; i++) {
            sum += i;         // ループならフレームは1つのまま
        }
        return sum;
    }
}

try {
    Deep.dive();
} catch (StackOverflowError e) {
    // 確かめるために捕まえているだけ。本番のコードで Error を catch して続行してはいけない
    System.out.println("StackOverflowError を捕まえた");
    System.out.println("1000 段より深く潜れていた? " + (Deep.depth > 1000));
    // 実際の段数は JVM の設定や実行のたびに変わるので、ここでは表示しない
}

// ここを変えてみよう:1_000_000 を 10_000_000 にしても、ループならあふれない
System.out.println("ループで 1〜100万を合計: " + Deep.sumLoop(1_000_000));

